    // let the first snapshot overwrite everything it just guessed.
    for (let playerId = 1; playerId <= this.welcome.maximumPlayers; playerId += 1) {
      this.world.addPlayer(playerId);
    }
    this.world.tick = this.welcome.serverTick;
    // Prediction must run the exact same command ticks that the server will
    // consume. Keep the local simulation ahead of the authoritative clock by
    // `leadTicks`; never retimestamp an already-predicted command on send.
    // Retimestamping made the client apply input N at tick N while the server
    // applied it at N + leadTicks, guaranteeing a correction every snapshot.
